$ErrorActionPreference='Stop'
$base='http://127.0.0.1:5088'
$outbox=Join-Path $env:TEMP 'opencode\lavafacil-mail-outbox'
$s=New-Object Microsoft.PowerShell.Commands.WebRequestSession
$checks=@()
function Add-Check($n,$ok,$detail){$script:checks += [pscustomobject]@{prueba=$n;estado=if($ok){'PASS'}else{'FAIL'};detalle=$detail}}
function Call($method,$path,$body=$null,$headers=@()){
  $h=@{'X-CSRF-TOKEN'=$script:csrf}; foreach($x in $headers.GetEnumerator()){$h[$x.Key]=$x.Value}
  try { $r=Invoke-WebRequest -UseBasicParsing -WebSession $script:s -Method $method -Uri ($script:base+$path) -Headers $h -ContentType 'application/json' -Body ($(if($null -ne $body){$body|ConvertTo-Json -Compress}else{$null})); return [pscustomobject]@{Status=[int]$r.StatusCode;Body=$r.Content} }
  catch { if($_.Exception.Response){$rr=$_.Exception.Response; $sr=New-Object IO.StreamReader($rr.GetResponseStream()); return [pscustomobject]@{Status=[int]$rr.StatusCode;Body=$sr.ReadToEnd()} }; throw }
}
$b=Invoke-WebRequest -UseBasicParsing -WebSession $s -Uri ($base+'/api/bootstrap'); $bj=$b.Content|ConvertFrom-Json; $script:csrf=$bj.token
Add-Check 'bootstrap mailReady y correoConfigurado con outbox' ($bj.mailReady -and $bj.correoConfigurado) ("status=$($b.StatusCode); mailReady=$($bj.mailReady); correoConfigurado=$($bj.correoConfigurado)")
$stamp=[DateTime]::UtcNow.ToString('yyyyMMddHHmmss'); $a1="autotest.correo.$stamp.1"; $a2="autotest.correo.$stamp.2"; $e1="$a1@example.com"; $e2="$a2@example.com"; # Clave de fixture generada en tiempo de ejecución; no se versiona ningún valor real.
$pw=if($env:LAVAFACIL_TEST_PASSWORD){$env:LAVAFACIL_TEST_PASSWORD}else{'Temporal-'+[guid]::NewGuid().ToString('N')+'!Aa1'}
function Register($u,$email,$id){ Call 'POST' '/api/register' @{identity=$id;name='AUTOTEST';lastName='CORREO';phone='5551234567';email=$email;address='prueba';username=$u;password=$pw} }
$r1=Register $a1 $e1 "AC-$stamp-1"; Add-Check 'registro cuenta correo 1' ($r1.Status -eq 200) "status=$($r1.Status)"
$b=Invoke-WebRequest -UseBasicParsing -WebSession $s -Uri ($base+'/api/bootstrap'); $script:csrf=($b.Content|ConvertFrom-Json).token
$r=Call 'GET' '/api/email/estado'; $j=$r.Body|ConvertFrom-Json; Add-Check 'GET estado correo autenticado' ($r.Status -eq 200 -and $j.correoConfigurado -eq $true) "status=$($r.Status); configurado=$($j.correoConfigurado)"
$before=(Get-ChildItem $outbox -Filter *.eml -ErrorAction SilentlyContinue).Count; $r=Call 'POST' '/api/email/verificacion/enviar' @{}; $after=(Get-ChildItem $outbox -Filter *.eml).Count; $eml=(Get-ChildItem $outbox -Filter *.eml|Sort-Object LastWriteTime|Select-Object -Last 1); $txt=Get-Content -Raw $eml.FullName; $code=[regex]::Match($txt,'(?im)^Codigo:\s*(\d{6})\s*$').Groups[1].Value; $sinHeader=($txt -notmatch '(?im)^X-LavaFacil-Codigo\s*:'); $sinOtpSubject=($txt -notmatch '(?im)^Subject:.*\d{6}'); Add-Check 'enviar verificacion crea EML y codigo solo cuerpo outbox' ($r.Status -eq 200 -and $after -eq ($before+1) -and $code.Length -eq 6) "status=$($r.Status); emlIncremento=$($after-$before); codigoExtraidoDelCuerpo=$($code.Length -eq 6)"; Add-Check 'EML verificacion no expone OTP en header ni Subject' ($sinHeader -and $sinOtpSubject) "sinHeader=$sinHeader; sinOtpSubject=$sinOtpSubject"
$r=Call 'POST' '/api/email/verificacion/confirmar' @{codigo=$code}; $j=$r.Body|ConvertFrom-Json; Add-Check 'confirmar verificacion correcta' ($r.Status -eq 200 -and $j.verificado) "status=$($r.Status); verificado=$($j.verificado)"
$b=Invoke-WebRequest -UseBasicParsing -WebSession $s -Uri ($base+'/api/bootstrap'); $script:csrf=($b.Content|ConvertFrom-Json).token; $r=Call 'POST' '/api/logout' @{}; $b=Invoke-WebRequest -UseBasicParsing -WebSession $s -Uri ($base+'/api/bootstrap'); $script:csrf=($b.Content|ConvertFrom-Json).token; $r2=Register $a2 $e2 "AC-$stamp-2"; Add-Check 'registro cuenta correo 2 para prueba token invalido' ($r2.Status -eq 200) "status=$($r2.Status)"
$b=Invoke-WebRequest -UseBasicParsing -WebSession $s -Uri ($base+'/api/bootstrap'); $script:csrf=($b.Content|ConvertFrom-Json).token
$r=Call 'POST' '/api/email/verificacion/enviar' @{}; $eml=(Get-ChildItem $outbox -Filter *.eml|Sort-Object LastWriteTime|Select-Object -Last 1); $txt=Get-Content -Raw $eml.FullName; $bad=[regex]::Match($txt,'(?m)^Codigo:\s*(\d{6})$').Groups[1].Value; if($bad -ne '000000'){$bad='000000'}else{$bad='000001'}; $badStatuses=@(); 1..5|%{$x=Call 'POST' '/api/email/verificacion/confirmar' @{codigo=$bad};$badStatuses+=$x.Status}; $st=Call 'GET' '/api/email/estado'; $sj=$st.Body|ConvertFrom-Json; Add-Check 'codigo incorrecto persiste intentos y quema token' (($badStatuses.Count -eq 5) -and ($sj.intentosRestantes -lt 5)) "statuses=$($badStatuses -join ','); intentosRestantes=$($sj.intentosRestantes)"
$b=Invoke-WebRequest -UseBasicParsing -WebSession $s -Uri ($base+'/api/bootstrap'); $script:csrf=($b.Content|ConvertFrom-Json).token; $r=Call 'POST' '/api/logout' @{}; $b=Invoke-WebRequest -UseBasicParsing -WebSession $s -Uri ($base+'/api/bootstrap'); $script:csrf=($b.Content|ConvertFrom-Json).token; $r=Call 'POST' '/api/login' @{username=$a1;password=$pw}; Add-Check 'login cuenta correo 1' ($r.Status -eq 200) "status=$($r.Status)"
$b=Invoke-WebRequest -UseBasicParsing -WebSession $s -Uri ($base+'/api/bootstrap'); $script:csrf=($b.Content|ConvertFrom-Json).token
$beforeRecoveryFiles=@(Get-ChildItem $outbox -Filter *.eml -ErrorAction SilentlyContinue | ForEach-Object FullName)
$existing=Call 'POST' '/api/email/recuperacion/solicitar' @{identificador=$e1}; $unknown=Call 'POST' '/api/email/recuperacion/solicitar' @{identificador="noexiste.$stamp@example.invalid"}; $same=(($existing.Body|ConvertFrom-Json).message -eq ($unknown.Body|ConvertFrom-Json).message); Add-Check 'recuperacion no enumera existente/inexistente' ($existing.Status -eq 200 -and $unknown.Status -eq 200 -and $same) "existente=$($existing.Status); inexistente=$($unknown.Status); cuerpoIdentico=$same"
$recoveryCandidates=@(Get-ChildItem $outbox -Filter *.eml -ErrorAction SilentlyContinue | Where-Object { $beforeRecoveryFiles -notcontains $_.FullName } | ForEach-Object { $p=$_; $t=Get-Content -Raw $p.FullName; $to=[regex]::Match($t,'(?im)^To:\s*(.+?)\s*$').Groups[1].Value.Trim(); $purpose=[regex]::Match($t,'(?im)^X-LavaFacil-Proposito:\s*(.+?)\s*$').Groups[1].Value.Trim(); if($to -ieq $e1 -and $purpose -ieq 'recuperacion'){[pscustomobject]@{Path=$p.FullName;To=$to;Purpose=$purpose}} })
$eml=if($recoveryCandidates.Count -eq 1){Get-Item $recoveryCandidates[0].Path}else{$null}; $txt=if($eml){Get-Content -Raw $eml.FullName}else{''}; $rc=[regex]::Match($txt,'(?im)^Codigo:\s*(\d{6})\s*$').Groups[1].Value; $sinHeader=($txt -notmatch '(?im)^X-LavaFacil-Codigo\s*:'); $sinOtpSubject=($txt -notmatch '(?im)^Subject:.*\d{6}'); $new=if($env:LAVAFACIL_TEST_PASSWORD){$env:LAVAFACIL_TEST_PASSWORD}else{'Temporal-'+[guid]::NewGuid().ToString('N')+'!Aa1'}; $r=if($rc.Length -eq 6){Call 'POST' '/api/email/recuperacion/restablecer' @{identificador=$e1;codigo=$rc;nuevaClave=$new}}else{[pscustomobject]@{Status=0;Body='No se encontró exactamente un EML NUEVO de recuperacion para el destinatario de prueba'}}; Add-Check 'seleccionar EML nuevo de recuperacion por To y proposito' ($recoveryCandidates.Count -eq 1 -and $rc.Length -eq 6) "candidatos=$($recoveryCandidates.Count); to=$($recoveryCandidates[0].To); proposito=$($recoveryCandidates[0].Purpose); codigoExtraidoDelCuerpo=$($rc.Length -eq 6)"; Add-Check 'EML recuperacion no expone OTP en header ni Subject' ($sinHeader -and $sinOtpSubject) "sinHeader=$sinHeader; sinOtpSubject=$sinOtpSubject"; Add-Check 'restablecer clave con codigo outbox' ($r.Status -eq 200) "status=$($r.Status); cuerpo=$($r.Body)"
$b=Invoke-WebRequest -UseBasicParsing -WebSession $s -Uri ($base+'/api/bootstrap'); $script:csrf=($b.Content|ConvertFrom-Json).token; $r=Call 'POST' '/api/logout' @{}; $b=Invoke-WebRequest -UseBasicParsing -WebSession $s -Uri ($base+'/api/bootstrap'); $script:csrf=($b.Content|ConvertFrom-Json).token; $r=Call 'POST' '/api/login' @{username=$a1;password=$new}; Add-Check 'login con nueva clave' ($r.Status -eq 200) "status=$($r.Status)"
$checks|ConvertTo-Json -Depth 4
